export function LeadwayLogo({
  width = 48,
  height = 48,
}: {
  width?: number;
  height?: number;
}) {
  const uid = useId();
  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 48 48"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
    >
      <rect width="48" height="48" fill={`url(#plw-${uid})`} />
      <defs>
        <pattern
          id={`plw-${uid}`}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref={`#ilw-${uid}`}
            transform="matrix(0.00191373 0 0 0.00184994 -0.733344 -1.71223)"
          />
        </pattern>
        <image
          id={`ilw-${uid}`}
          width="3369"
          height="2382"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
}

